          n:String(weekIdx(viewWk).indexOf(idx) + 1), title:l.t[i], sub:(l.mine?(i?'Parent-made · ':'Ba mẹ tạo · '):'') + SKILLS[l.sk][i] + ' · ' + l.m[i],
          state: done ? t.finished : (locked ? t.locked : (cur ? t.current : t.open)),
