      ...(() => { const nC = lesson.cx.length, vI = Math.min(st.variant, nC - 1), more = vI < nC - 1;
        const nx = more ? [[i?'At home':'Ở nhà'], [i?'At school':'Trên lớp'], [i?'Out there':'Ngoài đời']][lesson.cx[vI + 1].k][0] : '';
        return { fbNextLabel: more ? (i ? `Next situation: ${nx} →` : `Tình huống tiếp theo: ${nx} →`) : t.toQuiz,
          fbNext: () => { this.stopSpeak(); return more ? this.set({variant: vI + 1, step:'story', choice:null, reading:false}) : this.set({step:'quiz'}); } }; })(),
      storyText: vv ? vv.s[i] : lesson.story[i],
