          mark:`width:26px;height:26px;border-radius:9px;flex:none;display:flex;align-items:center;justify-content:center;font-size:12.5px;font-weight:700;color:${show&&right?'#FFF':'#5C4B3C'};background:${show&&right?JADE:'#F3E6D3'}`
