          reward: m.rw ? m.rw[i] : '', rewardLabel: t.rewardLabel,
          rewardRow: `display:flex;gap:8px;align-items:center;margin-top:9px;padding:9px 11px;border-radius:14px;background:${ap?'#DDF0E6':'#FFF6E4'};border:1.5px dashed ${ap?'#8FCBAA':'#F0CE8C'}`,
          rewardIcon: `width:20px;height:20px;border-radius:7px;flex:none;background:${ap?JADE:GOLD}`,
