        stars: (() => { const pi = +mk.split('-')[0], kp = st.profiles[pi], w = kp ? this.weekOf(st.weekLog, kp.name).stars : 0, g = Math.min(MISSION_STARS[lv], WEEK_CAP - w);
          return g > 0 ? '+' + g + (i?' stars':' sao') : (i?`${WEEK_CAP} stars reached`:`Đã đủ ${WEEK_CAP} sao tuần này`); })(),
