      showPay: st.pay!==null, payIdle: st.pay==='idle', payDone: st.pay==='done',
      openPay:()=> canPay ? this.set({pay:'idle', payKind:'plan', payRefCopied:false}) : null,
      closePay:()=>this.set({pay:null, payKind:null}),
      confirmPay:()=>this.setState(p=>{
        if (p.payKind==='profile' && p.pendingProfile) {
          return {pay:'done', profiles:[...p.profiles.slice(0,-1), p.pendingProfile, p.profiles[p.profiles.length-1]]};
        }
        const pl = p.plan || 'premium', owned = {};
        SKILLS.forEach((_,k)=>{ if (pl==='premium' || p.picked[k]) owned[k] = true; });
        return {pay:'done', owned, curPlan:pl};
      }),
