      tryDemo:()=>{ try { sessionStorage.setItem('senapp.demo','1'); } catch (e) {} this.set({gate:'welcome', demo:true}); },
      showNotReg: !st.family, notRegLabel: i?'Not registered yet?':'Bạn chưa đăng ký?',
