      onMPhone:(e)=>this.set({mPhone:e.target.value.replace(/[^\d ]/g,'').slice(0,13), mErr:''}),
      onMPin:(e)=>this.set({mPin:e.target.value.replace(/\D/g,'').slice(0,4), mErr:''}),
      hasMErr: !!st.mErr, mErr: st.mErr,
      doMLogin:()=>this.mLogin(), mBtn: i?'Log in':'Đăng nhập',
